<script setup lang="ts">
const api = useApi(), auth = useAuth(), notice = useNotice()
const data = ref<any>(null), loading = ref(true)
async function load() { loading.value = true; try { data.value = await api('/api/dashboard') } catch (e) { notice.show(errorMessage(e), 'error') } finally { loading.value = false } }
onMounted(load)
const stats = computed(() => [{ label: 'Cards owned', value: data.value?.counts.copies || 0, icon: 'cards', note: 'Physical copies recorded' }, { label: 'Unique printings', value: data.value?.counts.owned_printings || 0, icon: 'grid', note: 'Across your collection' }, { label: 'On your wishlist', value: data.value?.counts.wishlist || 0, icon: 'star', note: 'Printings you are tracking' }, { label: 'Your binders', value: data.value?.counts.binders || 0, icon: 'binder', note: 'Independent layout plans' }])
</script>
<template><header class="page-heading"><div><span class="eyebrow">YOUR WORKSPACE</span><h1>Collection overview</h1><p>A little organisation. A lot of possibility.</p></div><button class="icon-button bordered" aria-label="Refresh overview" :disabled="loading" @click="load"><AppIcon name="refresh" /></button></header><section class="welcome-banner"><div><span class="banner-label"><span class="status-dot" />YOUR OWN CORNER OF THE HOBBY</span><h2>Welcome back, {{ auth.state.value.user?.name?.split(' ')[0] }}.</h2><p>Keep track of what you own.<br>Make a little space for what comes next.</p><NuxtLink to="/cards" class="button white">Explore your cards<AppIcon name="arrow" :size="18" /></NuxtLink></div><div class="hero-art" aria-hidden="true"><div class="hero-card back" /><div class="hero-card front"><AppIcon name="binder" :size="60" /><span>THE NEXT<br>GREAT FIND.</span></div></div></section><section class="stats-grid"><article v-for="stat in stats" :key="stat.label" class="stat-card"><div class="stat-label">{{ stat.label }}<span class="stat-icon"><AppIcon :name="stat.icon" /></span></div><strong>{{ loading ? '—' : stat.value.toLocaleString() }}</strong><small>{{ stat.note }}</small></article></section><PriceSummary :refresh-key="data?.counts.copies || 0" /><div class="section-heading"><div><h2>Your binders</h2><p>Plan it digitally. Build it in real life.</p></div><NuxtLink to="/binders?new=1" class="button secondary"><AppIcon name="plus" :size="18" />New binder</NuxtLink></div><div v-if="data?.binders.length" class="binder-list"><NuxtLink v-for="binder in data.binders" :key="binder.id" :to="'/binders/' + binder.id" class="binder-card"><div class="binder-cover" :style="{ '--binder-color': binder.color }"><div class="binder-rings"><i /><i /><i /></div><AppIcon name="binder" :size="40" /><span>{{ binder.title }}</span><small>{{ binder.columns }} × {{ binder.rows }} POCKET LAYOUT</small></div><div class="binder-card-info"><strong>{{ binder.title }}</strong><span>{{ binder.filled }} / {{ binder.columns * binder.rows * binder.page_count }} pockets planned</span></div></NuxtLink></div><section v-else class="empty-state horizontal"><div class="empty-icon"><AppIcon name="binder" :size="36" /></div><div><h3>Your first binder starts here.</h3><p>Create a layout for a set, your favourites, or the cards you are still chasing.</p></div><NuxtLink to="/binders?new=1" class="text-button">Create a binder<AppIcon name="arrow" :size="17" /></NuxtLink></section><section class="panel collection-progress"><div class="section-heading"><div><h2>Set progress</h2><p>Unique card designs owned, compared with your imported catalogue.</p></div><span class="badge">{{ data?.counts.catalogue_cards?.toLocaleString() || 0 }} cards in catalogue</span></div><div v-if="data?.progress.length" class="progress-list"><div v-for="set in data.progress" :key="set.id" class="progress-row"><div><NuxtLink :to="{ path: '/cards', query: { set: set.id } }">{{ set.name }}</NuxtLink><span class="badge">{{ set.language.toUpperCase() }}</span><small v-if="set.imported < set.card_count" class="amber-text">Partial import · {{ set.imported }}/{{ set.card_count }}</small></div><div class="progress-track"><div :style="{ width: (set.owned / Math.max(1, set.imported) * 100) + '%' }" /></div><span>{{ set.owned }} / {{ set.imported }}</span></div></div><div v-else class="empty-inline"><p>Your catalogue is empty. Import a set to start collecting.</p><NuxtLink v-if="auth.state.value.user?.role === 'admin'" to="/settings#catalogue" class="button primary"><AppIcon name="download" :size="18" />Import your first set</NuxtLink><p v-else>Ask your administrator to import the sets you collect.</p></div></section><AdSenseSlot :content-ready="!!data && data.counts.catalogue_cards > 0" auto-only /></template>
